def signal(obs):
    # IDX vs basket arbitrage: fade basis deviations from rolling mean
    try:
        mI = obs.hist('IDX','mid',120)
        mA = obs.hist('A','mid',120)
        mB = obs.hist('B','mid',120)
        mC = obs.hist('C','mid',120)
        import math as _m
        # need enough history
        nav = [0.3333*a+0.6667*b+0.1667*c for a,b,c in zip(mA,mB,mC)]
        basis = [i-n for i,n in zip(mI,nav)]
        # rolling mean over 100
        valid=[x for x in basis if x==x]
        if len(valid)<100:
            return {}
        mean=sum(valid[-100:])/100
        # std
        v=sum((x-mean)**2 for x in valid[-100:])/100
        sd=_m.sqrt(v) if v>0 else 1.0
        z=(basis[-1]-mean)/(sd+1e-9)
        # thresholds: trade if |z|>1.5, size proportional capped
        if z>1.5:
            # IDX rich: short IDX, long basket
            k=min(1.0,(z-1.5)/2.0+0.3)
            return {'IDX':-k,'A':0.3333*k,'B':0.6667*k,'C':0.1667*k}
        elif z<-1.5:
            k=min(1.0,(-z-1.5)/2.0+0.3)
            return {'IDX':k,'A':-0.3333*k,'B':-0.6667*k,'C':-0.1667*k}
        else:
            return {'IDX':0.0,'A':0.0,'B':0.0,'C':0.0}
    except Exception:
        return {}

