def signal(obs):
    # IDX vs basket: fade large deviations only
    mI = obs.hist('IDX','mid',120)
    mA = obs.hist('A','mid',120)
    mB = obs.hist('B','mid',120)
    mC = obs.hist('C','mid',120)
    n = len(mI)
    if n < 110:
        return {}
    nav_last = 0.3333*mA[-1]+0.6667*mB[-1]+0.1667*mC[-1]
    basis_now = mI[-1]-nav_last
    # rolling mean over last 100 of basis
    s = 0.0
    c = 0
    for i in range(n-100, n):
        b = mI[i]-(0.3333*mA[i]+0.6667*mB[i]+0.1667*mC[i])
        if b==b:
            s += b; c += 1
    if c < 50 or mI[-1]!=mI[-1]:
        return {}
    mean = s/c
    dev = basis_now-mean
    if dev > 15:
