def signal(obs):
    # simple imbalance momentum: target proportional to imbalance
    import math
    targets = {}
    for asset in obs.assets:
        try:
            imb = obs.hist(asset, "imbalance", 5)
            # clean NaN
            vals = [x for x in imb if x==x]
            if len(vals)==0:
                continue
            avg = sum(vals)/len(vals)
            # scale: imb in [-1,1], target = 0.8* avg clipped
            t = max(-1,min(1, avg * 1.2))
            # deadzone small
            if abs(t) < 0.1:
                t = 0
            targets[asset] = t
        except Exception:
            continue
    return targets

