    if abs(r) < 8.0:
        t = 0.0
    if t > 0:
        out['COIN'] = float(t)
        out['COIN.P'] = 0.0
    elif t < 0:
        out['COIN.P'] = float(t)
        out['COIN'] = 0.0
    else:
